module photo_scheduler (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [7:0] t,\n    input [127:0] arr,\n    output reg result,\n    output reg done\n);\n\n    wire [7:0] a_unpacked [0:7];\n    wire [7:0] b_unpacked [0:7];\n\n    generate\n        genvar i;\n        for (i = 0; i < 8; i = i + 1) begin\n            assign a_unpacked[i] = arr[i*8 +: 8];\n            assign b_unpacked[i] = arr[64 + i*8 +: 8];\n        end\n    endgenerate\n\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] SORT = 3'd1;\n    localparam [2:0] SCHEDULE = 3'd2;\n    localparam [2:0] DONE = 3'd3;\n\n    reg [2:0] state;\n    reg [3:0] i_reg, j_reg;\n    reg [3:0] k_reg;\n    reg [7:0] a_reg [0:7];\n    reg [7:0] b_reg [0:7];\n    reg [15:0] current_time;\n\n    integer idx;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 1'b0;\n            i_reg <= 4'd0;\n            j_reg <= 4'd0;\n            k_reg <= 4'd0;\n            current_time <= 16'd0;\n            for (idx = 0; idx < 8; idx = idx + 1) begin\n                a_reg[idx] <= 8'd0;\n                b_reg[idx] <= 8'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        for (idx = 0; idx < 8; idx = idx + 1) begin\n                            a_reg[idx] <= a_unpacked[idx];\n                            b_reg[idx] <= b_unpacked[idx];\n                        end\n                        i_reg <= 4'd0;\n                        j_reg <= 4'd0;\n                        k_reg <= 4'd0;\n                        current_time <= 16'd0;\n                        if (n > 4'd1) begin\n                            state <= SORT;\n                        end else begin\n                            state <= SCHEDULE;\n                        end\n                    end\n                end\n                \n                SORT: begin\n                    if (j_reg < (n - i_reg - 4'd1)) begin\n                        if (b_reg[j_reg] > b_reg[j_reg + 4'd1]) begin\n                            a_reg[j_reg] <= a_reg[j_reg + 4'd1];\n                            a_reg[j_reg + 4'd1] <= a_reg[j_reg];\n                            b_reg[j_reg] <= b_reg[j_reg + 4'd1];\n                            b_reg[j_reg + 4'd1] <= b_reg[j_reg];\n                        end\n                        j_reg <= j_reg + 4'd1;\n                    end else begin\n                        i_reg <= i_reg + 4'd1;\n                        j_reg <= 4'd0;\n                        if (i_reg >= (n - 4'd1)) begin\n                            state <= SCHEDULE;\n                        end\n                    end\n                end\n                \n                SCHEDULE: begin\n                    if (k_reg < n) begin\n                        reg [15:0] temp_start_time;\n                        reg [15:0] temp_finish_time;\n                        temp_start_time = (current_time > {8'd0, a_reg[k_reg]}) ? current_time : {8'd0, a_reg[k_reg]} ;\n                        temp_finish_time = temp_start_time + {8'd0, t};\n                        if (temp_finish_time > {8'd0, b_reg[k_reg]}) begin\n                            result <= 1'b0;\n                            state <= DONE;\n                        end else begin\n                            current_time <= temp_finish_time;\n                            k_reg <= k_reg + 4'd1;\n                        end\n                    end else begin\n                        result <= 1'b1;\n                        state <= DONE;\n                    end\n                end\n                \n                DONE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule